<?php
namespace App\Console\Commands;
use App\Models\Booking;use App\Models\Branch;use App\Models\Customer;use App\Models\Organization;use App\Models\StorageLocation;use App\Models\TireSet;use App\Models\Vehicle;use App\Services\VehicleLookupService;use Illuminate\Console\Command;use Illuminate\Support\Facades\DB;use Illuminate\Support\Str;
class CreateDemoTenant extends Command
{
 protected $signature='demo:create-tenant {--source-org=1}';protected $description='Opprett eller fyll den isolerte DekkPilot-demovirksomheten';
 public function handle(VehicleLookupService $lookup):int{$registrations=['EV12345','EB12345','DR12345','SV12345','BR12345','EC12345','ED12345'];$vehicles=[];foreach($registrations as$registration){$vehicles[]=$lookup->lookup($registration,(int)$this->option('source-org'));}$org=DB::transaction(function()use($vehicles){$org=Organization::firstOrCreate(['organization_number'=>'DEMO-DEKKPILOT'],['public_id'=>(string)Str::uuid(),'name'=>'[DEMO] Nordisk Dekkhotell AS','email'=>'demo@example.no','subscription_status'=>'active']);$branch=Branch::firstOrCreate(['organization_id'=>$org->id,'code'=>'HOVED'],['public_id'=>(string)Str::uuid(),'name'=>'Demoavdeling Oslo','active'=>true]);$locations=[];foreach(['MOTTAK','A-01','A-02','B-01','B-02','C-01']as$i=>$code)$locations[]=StorageLocation::firstOrCreate(['branch_id'=>$branch->id,'code'=>$code],['public_id'=>(string)Str::uuid(),'organization_id'=>$org->id,'zone'=>$i===0?'Mottak':substr($code,0,1),'capacity'=>20,'active'=>true]);$names=['Ingrid Solberg','Martin Dahl','Nora Hansen','Emil Johansen','Sofie Berg','Henrik Moen','Maja Larsen'];$brands=['Nokian','Continental','Michelin','Goodyear','Bridgestone','Pirelli','Hankook'];foreach($vehicles as$i=>$data){$customer=Customer::firstOrCreate(['organization_id'=>$org->id,'customer_number'=>'DEMO'.str_pad((string)($i+1),3,'0',STR_PAD_LEFT)],['public_id'=>(string)Str::uuid(),'branch_id'=>$branch->id,'name'=>$names[$i],'email'=>'demokunde'.($i+1).'@example.no','phone'=>'9000000'.($i+1),'notes'=>'[DUMMY] Oppdiktet personalia; tekniske kjøretøydata fra Statens vegvesen.']);$vehicle=Vehicle::updateOrCreate(['organization_id'=>$org->id,'registration_number'=>$data['registration_number']],['public_id'=>(string)(Vehicle::withTrashed()->where('organization_id',$org->id)->where('registration_number',$data['registration_number'])->value('public_id')?:Str::uuid()),'customer_id'=>$customer->id,'make'=>$data['make'],'model'=>$data['model'],'model_year'=>$data['model_year'],'vin'=>$data['vin'],'recommended_tire_size'=>$data['recommended_tire_size']]);$season=$i%2===0?'winter':'summer';$set=TireSet::firstOrCreate(['organization_id'=>$org->id,'vehicle_id'=>$vehicle->id,'season'=>$season],['public_id'=>(string)Str::uuid(),'storage_location_id'=>$locations[($i%5)+1]->id,'code'=>'DEMO-HJ-'.str_pad((string)($i+1),3,'0',STR_PAD_LEFT),'kind'=>'complete_wheels','manufacturer'=>$brands[$i],'size'=>$data['recommended_tire_size'],'quantity'=>4,'minimum_tread_depth'=>[6.8,5.4,3.1,2.4,7.2,4.6,1.8][$i],'dot_year'=>now()->year-($i%6),'status'=>'stored','condition_notes'=>'[DUMMY]','received_at'=>now()->subDays(20+$i)]);if($i<5){$starts=now()->addDays($i+1)->setTime(9+$i,0);Booking::firstOrCreate(['organization_id'=>$org->id,'reference'=>'DEMO-B'.($i+1)],['public_id'=>(string)Str::uuid(),'branch_id'=>$branch->id,'customer_id'=>$customer->id,'vehicle_id'=>$vehicle->id,'service_name'=>$i%2?'Dekkhotell':'Sesongskift','agreed_price_cents'=>$i%2?129900:69900,'starts_at'=>$starts,'ends_at'=>$starts->copy()->addMinutes(45),'status'=>'scheduled','notes'=>'[DUMMY]']);}}return$org;});$this->info('Demovirksomhet klar: '.$org->name.' (ID '.$org->id.') med '.count($vehicles).' kjøretøy.');return self::SUCCESS;}
}
